        const rows = Math.ceil(n / cols); let hs = PY;
        for (let r = 0; r < rows; r++) { const sl = M.cards.slice(r * cols, r * cols + cols); hs += Math.max(...sl.map((c) => hOf(c.t))) + (cols > 1 ? 24 : 0) + (r < rows - 1 ? GY : 0); }
