      if (!drag.moved) { drag.moved = true; drag.g = doc.createElement('div'); drag.g.className = 'ghost'; drag.g.innerHTML = ic('i-table', 16, 'ic f-obj') + '<span class="mono">' + drag.t + '</span>'; win.appendChild(drag.g); }
