        while (k < ptoks.length) { const n = 3 + Math.floor(Math.random() * 6), part = ptoks.slice(k, k + n).join(''); k += n; const end = k >= ptoks.length; at(jit(38, 62), () => { acc += part; ans.innerHTML = proseHTML((acc.match(/\*\*/g) || []).length % 2 ? acc.replace(/\*\*(?=[^*]*$)/, '') : acc) + (end ? '' : BAR); scrollThread(); }); }
